// 1. Obtener el stdout de SSH que contiene el JSONL del transcript
const logContent = $input.item.json.stdout || '';

// Dividir por líneas y recorrer en reversa
const lines = logContent.trim().split('\n').reverse();

let lastResponse = '';
for (const line of lines) {
  try {
    const data = JSON.parse(line);
    if (data.source === 'MODEL' && data.type === 'PLANNER_RESPONSE' && data.content && data.content.trim()) {
      lastResponse = data.content;
      break;
    }
  } catch (e) {
    // Ignorar líneas vacías o corruptas
  }
}

if (!lastResponse) {
  return [{
    json: {
      stdout_clean: "No se encontró respuesta en la sesión activa."
    }
  }];
}

// 2. Función para convertir Markdown al subconjunto HTML de Telegram de forma segura
function markdownToHtml(text) {
  // Preprocesar elementos HTML no soportados por Telegram
  let processedText = text;

  // 1. Convertir listas ordenadas <ol> y desordenadas <ul> de manera robusta
  processedText = processedText.replace(/<ol[^>]*>([\s\S]*?)<\/ol>/gi, (match, listContent) => {
    let index = 1;
    return listContent.replace(/<li[^>]*>([\s\S]*?)<\/li>\s*\n?/gi, (liMatch, itemContent) => {
      return `${index++}. ${itemContent.trim()}\n`;
    });
  });

  processedText = processedText.replace(/<ul[^>]*>([\s\S]*?)<\/ul>/gi, (match, listContent) => {
    return listContent.replace(/<li[^>]*>([\s\S]*?)<\/li>\s*\n?/gi, (liMatch, itemContent) => {
      return `• ${itemContent.trim()}\n`;
    });
  });

  // Fallback para <li> huérfanos
  processedText = processedText.replace(/<li[^>]*>([\s\S]*?)<\/li>\s*\n?/gi, (match, itemContent) => {
    return `• ${itemContent.trim()}\n`;
  });

  // Limpiar tags de listas residuales
  processedText = processedText
    .replace(/<\/?ul>/gi, '')
    .replace(/<\/?ol>/gi, '');

  // 2. Convertir otros tags HTML comunes no soportados por Telegram
  processedText = processedText
    .replace(/<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi, '<b>$1</b>\n')
    .replace(/<p[^>]*>([\s\S]*?)<\/p>\s*\n?/gi, '$1\n\n')
    .replace(/<div[^>]*>([\s\S]*?)<\/div>\s*\n?/gi, '$1\n')
    .replace(/<br\s*\/?>/gi, '\n');

  // 3. Placeholderize valid Telegram HTML tags
  const placeholders = [];
  let placeholderCounter = 0;

  const validTagRegex = /<\/?(?:b|strong|i|em|u|ins|s|strike|del|code|pre|tg-spoiler)(?:\s+[^>]*)*>|<\/?span(?:\s+class=["']tg-spoiler["'])?\s*>|<\/?a(?:\s+href=["'][^"']*["'])?\s*>/gi;

  processedText = processedText.replace(validTagRegex, (match) => {
    const placeholder = `___VALID_TAG_PLACEHOLDER_${placeholderCounter}___`;
    placeholders.push({ placeholder, original: match });
    placeholderCounter++;
    return placeholder;
  });

  // 2. Escape remaining HTML characters to protect against invalid tags breaking Telegram parser
  processedText = processedText
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // 3. Restore valid HTML tags
  for (const p of placeholders) {
    processedText = processedText.replace(p.placeholder, p.original);
  }

  // 4. Convert Markdown to HTML
  // Convertir bloques de código: ```js [codigo] ``` -> <pre><code>$1</code></pre>
  processedText = processedText.replace(/```(?:[a-zA-Z0-9_+#-]+)?\n([\s\S]*?)\n```/g, '<pre><code>$1</code></pre>');

  // Convertir código en línea: `codigo` -> <code>codigo</code>
  processedText = processedText.replace(/`([^`\n]+)`/g, '<code>$1</code>');

  // Convertir negritas: **texto** -> <b>texto</b>
  processedText = processedText.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
  processedText = processedText.replace(/__([^_]+)__/g, '<b>$1</b>');

  // Convertir itálicas: *texto* -> <i>texto</i> o _texto_ -> <i>texto</i>
  processedText = processedText.replace(/\*([^*]+)\*/g, '<i>$1</i>');
  processedText = processedText.replace(/\b_([^_]+)_\b/g, '<i>$1</i>');

  // Convertir enlaces Markdown: [texto](url) -> <a href="url">texto</a>
  processedText = processedText.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');

  // Convertir encabezados: ### texto -> <b>texto</b>
  processedText = processedText.replace(/^(?:#{1,6})\s+(.+)$/gm, '<b>$1</b>');

  return processedText;
}

// 3. Función para segmentar el texto limpiamente por saltos de línea o espacios
function chunkString(str, limit) {
  const chunks = [];
  let index = 0;
  while (index < str.length) {
    if (str.length - index <= limit) {
      chunks.push(str.substring(index));
      break;
    }
    let cutPos = str.lastIndexOf('\n', index + limit);
    if (cutPos <= index) {
      cutPos = str.lastIndexOf(' ', index + limit);
    }
    if (cutPos <= index) {
      cutPos = index + limit;
    }
    chunks.push(str.substring(index, cutPos));
    index = cutPos + 1;
  }
  return chunks;
}

// Segmentar sobre el texto markdown original
const CHAR_LIMIT = 4000;
const chunks = chunkString(lastResponse, CHAR_LIMIT);

// Convertir a HTML cada fragmento de forma independiente
return chunks.map(chunk => ({
  json: {
    stdout_clean: markdownToHtml(chunk.trim())
  }
}));
